<?php
declare(strict_types=1);
require dirname(__DIR__).'/app/bootstrap.php';
$u=require_admin($pdo);header('Cache-Control: private, no-store');$error='';$success='';
if($_SERVER['REQUEST_METHOD']==='POST'){require_csrf();try{$build=sponsored_research_dataset_assemble($pdo,$u,(string)($_POST['release_id']??''),(string)($_POST['purpose']??''),(string)($_POST['name']??''));$success='Dataset '.$build['dataset_name'].' v'.$build['dataset_version'].' assembled and frozen.';}catch(Throwable $e){$error=$e->getMessage();}}
$releases=$pdo->query("SELECT kr.public_id,kr.release_number,kr.manifest_hash,kr.item_count,kb.name knowledge_base_name,c.title campaign_title FROM sponsored_research_knowledge_releases kr JOIN sponsored_research_knowledge_bases kb ON kb.id=kr.knowledge_base_id JOIN sponsored_research_campaigns c ON c.id=kb.campaign_id ORDER BY kr.id DESC LIMIT 250")->fetchAll()?:[];
$builds=sponsored_research_dataset_builds($pdo,250);
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Sponsored Research Datasets · Admin</title><link rel="stylesheet" href="/assets/css/app.css"></head><body><main class="panel"><div class="pageTitle"><span class="eyebrow">PHASE 80 · DATASET AUTHORITY</span><h1>Sponsored Research Datasets</h1><p>Assemble canonical Dataset Registry versions from immutable Knowledge releases. Participation never implies training consent; every promoted item must carry explicit purpose-specific consent and current Source rights.</p></div>
<?php if($error):?><div class="error"><?=h($error)?></div><?php endif?><?php if($success):?><div class="success"><?=h($success)?></div><?php endif?>
<section class="card"><h2>Assemble dataset</h2><form method="post" class="stack"><?=csrf_field()?><label>Knowledge release<select name="release_id" required><option value="">Select release</option><?php foreach($releases as $r):?><option value="<?=h((string)$r['public_id'])?>"><?=h((string)$r['campaign_title'])?> · <?=h((string)$r['knowledge_base_name'])?> v<?=h((string)$r['release_number'])?> · <?=h((string)$r['item_count'])?> items</option><?php endforeach?></select></label><label>Purpose<select name="purpose" required><option value="shared_retrieval">Shared retrieval</option><option value="evaluation">Evaluation</option><option value="training">Training</option><option value="commercial_training">Commercial training</option></select></label><label>Dataset name (optional)<input name="name"></label><button>Assemble and freeze</button></form></section>
<section class="card"><h2>Sponsored lineage builds</h2><?php if(!$builds):?><p>No sponsored datasets yet.</p><?php else:?><table><thead><tr><th>Campaign / KB</th><th>Release</th><th>Purpose</th><th>Dataset</th><th>Current use</th></tr></thead><tbody><?php foreach($builds as $b):$st=sponsored_research_dataset_current_use_status($pdo,(string)$b['public_id']);?><tr><td><?=h((string)$b['campaign_title'])?><div class="meta"><?=h((string)$b['knowledge_base_name'])?></div></td><td>v<?=h((string)$b['release_number'])?></td><td><?=h((string)$b['purpose'])?></td><td><?=h((string)$b['dataset_name'])?> v<?=h((string)$b['dataset_version'])?></td><td><?=$st['usable']?'Current':'Blocked: '.h((string)$st['reason'])?></td></tr><?php endforeach?></tbody></table><?php endif?></section></main></body></html>